pipeline {
    agent any

    environment {
        REMOTE_HOST = '20.48.1.130' // 远程服务器地址
        REMOTE_USER = 'root' // 远程服务器用户名
        REMOTE_CREDENTIALS_ID = 'server-18-credentials-id' // Jenkins中保存的远程服务器SSH凭证ID
        REMOTE_ADDRESS = '/data/web/oa-mobile'  //远程服务器web文件地址
        TIMESTAMP = new Date().format("yyyyMMddHHmmss", TimeZone.getTimeZone('UTC'))
    }

    stages {
        stage('Git') {
            steps {
                echo "Trying to checkout code from gitlab branch: ${params.Branch}"
                checkout scmGit(branches: [[name: "${params.Branch}"]], extensions: [], userRemoteConfigs: [[credentialsId: 'SSH-KEY-FOR-GITLAB', url: '${GIALAB_ADDRESS}/front/digital-collaboration-app.git']])
            }
        }

        stage('Npm Install') {
            steps {
                nvm("v14.21.3") {
                    sh 'node -v'
                    sh 'npm install --no-frozen-lockfile'
                }
               // sh 'nvm use 16.20.2'
               // sh 'pnpm install'
                // 或者  sh 'yarn '

            }
        }

        // stage('SonarQube Analysis') {
        //     when {
        //         expression { params.CodeScan == true }
        //     }
        //     steps {
        //         script {
        //             scannerHome = tool 'sonar-scanner'
        //         }
        //         withSonarQubeEnv('SonarQube-dev') {
        //             sh"""
        //                 ${scannerHome}/bin/sonar-scanner \
        //                   -Dsonar.projectKey=${PROJECT_NAME} \
        //                   -Dsonar.sources=. \
        //                   -Dsonar.exclusions=node_modules/** \
        //                   -Dsonar.host.url=http://106.227.94.62:8848 \
        //                   -Dsonar.token=sqa_3aa649e14136888983f36950fe21a62f65c82e32 \
        //                   -Dsonar.skip=true
        //             """
        //         }
        //     }
        // }

        stage('Npm Build') {
            steps {
                 nvm("v14.21.3") {
                    sh 'node -v'
                    sh 'npm run build:dev'
                }
                // sh 'npm run build'
                // sh 'pnpm run build:dev'
                // 或者 sh "yarn build:${params.Branch}"
            }
        }


        stage('Deploy to Remote') {
            steps {
                script {
                    sh 'pwd'
                    sh 'tar -zcvf dist.tar.gz dist/'
                    sh 'scp dist.tar.gz root@${REMOTE_HOST}:${REMOTE_ADDRESS} ' 

                  sshagent([REMOTE_CREDENTIALS_ID]) {
                        sh """
                            ssh ${REMOTE_USER}@${REMOTE_HOST} '

                            cd ${REMOTE_ADDRESS}  &&

                            mv dist/ dist-${TIMESTAMP}/  &&

                            tar -zxvf dist.tar.gz  &&

                            rm -f dist.tar.gz



                            '
                           """
                    }

                }
            }
        }


    }
}
